 if(x.tasks.deadline_extensions&&x.tasks.deadline_extensions->by_task.count(task->id))return common_failure("TaskPersonalMessageDeadlineExtensionUnsupported",s.fact_id);
 // 该新开工只能由本人显式命令签出，旧多Actor推进许可不会把别人变成当前Known listener。
 if(!x.player_before)return common_failure("TaskPersonalMessagePlayerSourceRequired",s.fact_id);auto player=x.player_before(s.started_tick,s.fact_id);if(!player.ok)return {false,{},player.error};if(player.value!=s.carrier_actor_id)return common_failure("TaskPersonalMessageHistoricalPlayerMismatch",s.fact_id);
 auto valid=x.personal.known_personal_dialogue_before_fact(proof,s.started_tick,s.fact_id);if(!valid.ok)return valid;valid=presence(x,s.carrier_actor_id,s.started_tick,s.fact_id);if(!valid.ok)return valid;return presence(x,s.recipient_actor_id,s.started_tick,s.fact_id);
