 if(const auto* live=c.action(s.action_id)){if((!x.phase&&!x.exact_clock)||e.tick!=(x.exact_clock?x.exact_clock->at.half_day_tick:x.phase->to_tick)||live->remaining_ticks!=0||live->kind!="deliver_message"||live->actor_id!=s.carrier_actor_id||live->start_tick!=s.started_tick||live->participants!=std::vector<StableId>{s.carrier_actor_id,s.recipient_actor_id})return common_failure("TaskPersonalMessageCompletedActionStillActive",s.action_id);}
 if(x.tasks.actions.find(s.action_id)&&!c.action(s.action_id))return common_failure("TaskPersonalMessageOrphanTaskAction",s.action_id);return common_success();
